from playwright.sync_api import sync_playwright
with sync_playwright() as p:
    b=p.chromium.launch(executable_path='/usr/bin/google-chrome',args=['--no-sandbox']); errs=[]
    G=b.new_page(viewport={'width':1440,'height':950}); G.on('pageerror',lambda e:errs.append(str(e)))
    G.goto('http://localhost:3300/#entry-imagic-armour-zenith'); G.wait_for_timeout(1500)
    G.click('[data-act=edit]'); G.wait_for_timeout(600); G.select_option('#it-cat','Land vehicle'); G.wait_for_timeout(300)
    print('resources box', G.locator('#it-res-on').is_visible(), '| other options hidden', not G.locator('#it-light-on').is_visible())
    G.check('#it-res-on'); G.wait_for_timeout(200)
    if not G.locator('.itresrow').count(): G.click('[data-act=itresadd]')
    G.locator('.itresrow .ir-name').first.fill('Missile pods'); G.wait_for_timeout(100)
    amt=G.locator('.itresrow input[type=number]').first; amt.fill('4')
    G.locator('.itresrow .ir-reset').first.select_option('short')
    G.click('[data-act=itresadd]'); G.locator('.itresrow .ir-name').nth(1).fill('Overdrive'); G.locator('.itresrow input[type=number]').nth(1).fill('1')
    G.screenshot(path='/tmp/vres-ed.png')
    G.click('form[data-form=entry] button[type=submit]'); G.wait_for_timeout(900)
    print('saved res', G.evaluate("JSON.stringify(S.entries.get('imagic-armour-zenith').item.res)"))
    G.goto('http://localhost:3300/#vtt'); G.wait_for_timeout(1000)
    G.click('[data-act=vttnewcamp]'); G.fill('#vaskv','Mech'); G.keyboard.press('Enter'); G.wait_for_timeout(1500)
    pid=G.evaluate("VTT.page"); cid=G.evaluate("[...S.chars].find(([,c])=>!c.hidden)[0]")
    G.evaluate(f"vPatch('vttcamps/'+vCampId(),{{playerPage:'{pid}'}}); vSave('vtttokens/z',{{page:'{pid}',layer:'token',x:3,y:3,size:2,img:'',name:'Zenith',ref:'e:imagic-armour-zenith',owner:'',hp:200,hpMax:200}}); vSave('vtttokens/pc',{{page:'{pid}',layer:'token',x:3,y:3,size:1,img:'',name:'Hero',ref:'c:{cid}',owner:'{cid}'}})"); G.wait_for_timeout(900)
    G.evaluate("VTT.sel={kind:'tok',id:'z'}; vRefresh()"); G.wait_for_timeout(300); print('GM panel', G.locator('.vvres').inner_text().replace('\n',' | '))
    G.locator('[data-act=vttvres][data-i="0"][data-d="-1"]').click(); G.wait_for_timeout(500); G.locator('[data-act=vttvres][data-i="0"][data-d="-1"]').click(); G.wait_for_timeout(700)
    print('after using 2', G.evaluate("JSON.stringify(S.vttTokens.get('z').vres)"))
    P=b.new_context(viewport={'width':1280,'height':850}).new_page(); P.on('pageerror',lambda e:errs.append('P '+str(e)))
    P.goto('http://192.0.2.2:3300/'); P.wait_for_timeout(800); P.click('[data-act=srvlogin][data-v=player]'); P.wait_for_timeout(2500)
    P.goto('http://192.0.2.2:3300/#vtt'); P.wait_for_timeout(800); P.click('.vcamp a >> nth=0'); P.wait_for_timeout(1800)
    P.evaluate("VTT.sel={kind:'tok',id:'z'}; vRefresh()"); P.wait_for_timeout(300); print('player not aboard: buttons', P.locator('[data-act=vttvres]').count())
    P.evaluate("vRideOn('pc','z')"); P.wait_for_timeout(1200); P.evaluate("VTT.sel={kind:'tok',id:'z'}; vRefresh()"); P.wait_for_timeout(300)
    print('player aboard: buttons', P.locator('[data-act=vttvres]').count())
    P.locator('[data-act=vttvres][data-i="1"][data-d="-1"]').click(); P.wait_for_timeout(1200); print('player used overdrive', G.evaluate("JSON.stringify(S.vttTokens.get('z').vres)"), P.locator('.toast').all_inner_texts()[-1:])
    P.click('[data-act=vttvrest][data-v=short]'); P.wait_for_timeout(1200); print('short rest', G.evaluate("JSON.stringify(S.vttTokens.get('z').vres)"))
    P.screenshot(path='/tmp/vres-player.png'); print('ERRORS', errs); b.close()
